import{_ as a}from"./chunks/demo.ADy1HxC7.js";import{_ as t,o,c as i,aa as r}from"./chunks/framework.BAs_AphD.js";const k=JSON.parse('{"title":"Co je Buildary","description":"","frontmatter":{"title":"Co je Buildary","wiki":"cs:firstofall:start"},"headers":[],"relativePath":"firstofall/index.md","filePath":"firstofall/index.md","lastUpdated":1794209661000}'),l={name:"firstofall/index.md"};function d(n,e,s,p,u,v){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="co-je-buildary" tabindex="-1">Co je Buildary <a class="header-anchor" href="#co-je-buildary" aria-label="Permalink to &quot;Co je Buildary&quot;">​</a></h1><p>Buildary je cloudová aplikace pro vedení staveb. Pracujete v ní v prohlížeči i v mobilní aplikaci a na každé stavbě si zapnete jen ty moduly, které potřebujete.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/co-je-buildary">Zjistit, co Buildary umí</a> v Akademii.</p><h2 id="moduly" tabindex="-1">Moduly <a class="header-anchor" href="#moduly" aria-label="Permalink to &quot;Moduly&quot;">​</a></h2><ul><li><strong><a href="/buildary-help-preview/diary/">Stavební deník</a></strong> – elektronický stavební deník podle stavebního zákona, včetně elektronického podpisu.</li><li><strong><a href="/buildary-help-preview/tickets/">Management úkolů</a></strong> – úkoly, vady a nedodělky přímo na výkresech a v mapě.</li><li><strong><a href="/buildary-help-preview/performedworks/">Soupisy provedených prací</a></strong> – měsíční soupisy prací zhotovitele i podzhotovitelů včetně schvalování.</li></ul><p>Moduly fungují samostatně, ale nejvíc vám ušetří, když je používáte společně: například úkol založíte přímo ze záznamu v deníku.</p><h2 id="kde-jsou-vase-data" tabindex="-1">Kde jsou vaše data <a class="header-anchor" href="#kde-jsou-vase-data" aria-label="Permalink to &quot;Kde jsou vaše data&quot;">​</a></h2><p>Buildary běží v cloudu Microsoft Azure. Data jsou chráněná před neoprávněným přístupem a ztrátou a neopustí území Evropské unie. Oprávnění lidé k nim mají přístup kdykoli a odkudkoli, kde je internet.</p><h2 id="jak-zacit" tabindex="-1">Jak začít <a class="header-anchor" href="#jak-zacit" aria-label="Permalink to &quot;Jak začít&quot;">​</a></h2><ol><li><a href="/buildary-help-preview/firstofall/access">Zaregistrujte se a přihlaste</a>.</li><li>Při prvním přihlášení si nechte vytvořit <strong>Demo stavbu</strong> (viz níže).</li><li><a href="/buildary-help-preview/firstofall/description">Zorientujte se v aplikaci</a>.</li><li>Pokud budete Buildary používat jako firma, <a href="/buildary-help-preview/firstofall/domain">založte firemní doménu</a>.</li><li>Až budete chtít pracovat naostro, <a href="/buildary-help-preview/diary/projectsetup">založte vlastní stavbu</a>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Demo stavba</p><p>Při prvním přihlášení vám aplikace nabídne volbu <strong>Pokračovat s demo stavbou</strong>. Doporučujeme ji – Demo stavba obsahuje ukázková data ve všech modulech, takže si vše vyzkoušíte bez rizika. Za 30 dní se sama smaže, proto do ní nevkládejte ostrá data. Při dalším přihlášení už ji aplikace nenabídne.</p></div><figure class="shot" style="--w:600px;"><img src="'+a+'" alt="Nabídka Demo stavby při prvním přihlášení" loading="lazy"></figure><h2 id="videa" tabindex="-1">Videa <a class="header-anchor" href="#videa" aria-label="Permalink to &quot;Videa&quot;">​</a></h2><p>Pokud se raději díváte než čtete, nejdůležitější témata vysvětlují <a href="https://www.youtube.com/playlist?list=PL3uJDDr4spKHscqIIixyXe3JQgdJXZ0Gk" target="_blank" rel="noreferrer">videa na YouTube</a>. Novější funkce v nich nemusí být – ty najdete v této nápovědě a v <a href="/buildary-help-preview/news/version_5-1-0">Novinkách</a>.</p>',14)])])}const m=t(l,[["render",d]]);export{k as __pageData,m as default};
